const wait = (ms) => new Promise((r) => setTimeout(() => r(ms), ms));
assert.deepEqual(await mod.mapLimit([30, 10, 20], 2, (ms) => wait(ms)), [30, 10, 20]);

let active = 0;
let peak = 0;
const fn = async (x) => { active++; peak = Math.max(peak, active); await new Promise((r) => setTimeout(r, 5)); active--; return x * 2; };
const out = await mod.mapLimit([1, 2, 3, 4, 5, 6, 7, 8, 9], 3, fn);
assert.deepEqual(out, [2, 4, 6, 8, 10, 12, 14, 16, 18]);
assert.equal(peak, 3);

// every call waits on a gate the test opens by hand, so the count does not depend on timer resolution
const gates = new Map();
const started = [];
const fn = (x) => { started.push(x); return new Promise((resolve, reject) => gates.set(x, { resolve, reject })); };
const flush = () => new Promise((r) => setImmediate(r));
const outcome = mod.mapLimit([1, 2, 3, 4, 5, 6], 2, fn).then(() => null, (err) => err);
await flush();
assert.deepEqual([...started].sort(), [1, 2], 'two calls in flight');
gates.get(2).reject(new Error('bad item 2'));
await flush();
gates.get(1).resolve(1);
await flush();
const err = await outcome;
assert.ok(err instanceof Error && /bad item 2/.test(err.message), 'rejects with the failure: ' + err);
assert.deepEqual([...started].sort(), [1, 2], 'a call started after the failure: ' + started);

let calls = 0;
assert.deepEqual(await mod.mapLimit([], 4, async () => { calls++; }), []);
assert.equal(calls, 0);

